Lemma skip_space_shape : forall w c,
  snd (skip_space c w) = [] \/ (exists b r, snd (skip_space c w) = b :: r /\ is_ws b = false /\ (length (snd (skip_space c w)) <= length w)%nat /\ fst (skip_space c w) = c).
