(* [comment removed for export] *)
Definition act_fact (st b : Z) (a : act) : Prop :=
  match a with
  | AGoto s k => k = true /\ zw s <= 1
  | APop false => zw st = 1
  | AParseNumber => st = ST_NUMBER
  | AParseString => st = ST_STRING
  | AComma => st = ST_EXPECT_COMMA_OR_END
  | ASkip => is_ws b = true /\ zw st = 0
  | ASlash | ABegin _ | AEnd _ | AString _ | ANumber | ALit _ | APushCr | ALitDone | APop true => zw st <= 1
  | _ => True
