Definition hreach (c0 : ctrl) (w0 : list Z) (c : ctrl) (w : list Z) (evs : list evk) (al : Z) : Prop :=
  stack_ok c /\ forall F, Z.of_nat F > phi c w -> parse_some c0 w0 = pre evs al (loop F c w).
